def subject_page(s):
    url = f"study/{s['slug']}/"
    crumbs = [("Study Hub", "@@/study/"), (s["name"], "")]
    seq = "<table><thead><tr><th>Grade</th><th>Typical course(s)</th></tr></thead><tbody>" + "".join(f"<tr><td>{g}</td><td>{c}</td></tr>" for g, c in s["seq"]) + "</tbody></table>"
    topics = "".join(f"<h3>{t}</h3><p>{d}</p>" for t, d in s["topics"])
    strat = "<ol>" + "".join(f"<li>{x}</li>" for x in s["strategy"]) + "</ol>"
    mist = "<ul>" + "".join(f"<li>{x}</li>" for x in s["mistakes"]) + "</ul>"
    fq, fschema = faq(s["faq"])
    body = f'''<div class="toc"><strong>On this page</strong><ol><li><a href="#sequence">Course sequence</a></li><li><a href="#topics">Key topics</a></li><li><a href="#strategy">How to study</a></li><li><a href="#mistakes">Common mistakes</a></li><li><a href="#videos">Videos</a></li><li><a href="#quiz">Practice quiz</a></li><li><a href="#faq">FAQ</a></li></ol></div>
{s["intro"]}
<h2 id="sequence">Typical {e(s["name"])} course sequence</h2><p>Course names and order vary by state and school. This is the most common US pattern:</p>{seq}
<h2 id="topics">Key topics to master</h2>{topics}
{ad()}
<h2 id="strategy">How to study {e(s["name"]).lower()} effectively</h2>{strat}
<div class="callout t"><p><strong>Struggling with a specific unit?</strong> A few sessions with a tutor who diagnoses the exact gap can save weeks. <a href="@@/get-matched/?need=Tutoring">Get a free tutoring match →</a></p></div>
<h2 id="mistakes">Common mistakes to avoid</h2>{mist}
<h2 id="videos">Watch: free video lessons</h2><p>Hand-picked lessons from respected educational creators, played through YouTube’s privacy-enhanced player.</p>{vids(s["videos"])}
<h2 id="quiz">Practice quiz</h2>{quiz(s["name"] + " quick check", s["quiz"])}
{fq}
<h2>Keep going</h2><p>Explore the rest of the <a href="@@/study/">Study Hub</a>, plan your schedule with the <a href="@@/college/roadmap/">4-year roadmap</a>, and track your grades with the <a href="@@/tools/gpa-calculator/">GPA calculator</a>.</p>'''
    links = s["tools"] + [("All subjects", "@@/study/"), ("How to Study Effectively", "@@/guides/how-to-study/"), ("Video Library", "@@/videos/")]
    html = article(f'{s["emoji"]} High School {s["name"]} Study Guide', s["desc"], crumbs, body, links, f"{s['name']} page", "Tutoring", eyebrow="Study Hub")
    art = {"@context": "https://schema.org", "@type": "Article", "headline": f"High School {s['name']} Study Guide", "description": s["desc"], "author": {"@type": "Organization", "name": "High.School Editorial Team"}, "publisher": {"@type": "Organization", "name": "High.School"}}
    page(url, f"High School {s['name']} Study Guide", s["desc"], html + lead_band(need="Tutoring"), crumbs, [fschema, art], s["kw"])


def build():
    for s in SUBJECTS:
        subject_page(s)
    cards = "".join(f'<a class="card" href="@@/study/{s["slug"]}/"><div class="ico">{s["emoji"]}</div><h3>{s["name"]}</h3><p>{e(s["desc"][:118])}…</p></a>' for s in SUBJECTS)
    body = page_hero("The Study Hub", "Free, plain-English study guides for every core high school subject — with course roadmaps, key topics, common mistakes, video lessons and instant-feedback practice quizzes.", [("Study Hub", "")], eyebrow="10 subjects · 50 practice questions")
    body += f'''<div class="wrap"><section><div class="grid g3">{cards}</div></section>
<section class="prose narrow"><h2>How to use the Study Hub</h2><p>Each subject guide follows the same structure so you always know where to look: the <strong>typical course sequence</strong> (so you can plan ahead), the <strong>key topics</strong> teachers test most, a <strong>study method</strong> tailored to that subject, the <strong>mistakes</strong> that cost the most points, curated <strong>videos</strong>, and a <strong>5-question quiz</strong> with explanations.</p>
<p>For the science of studying itself — retrieval practice, spacing and interleaving — read <a href="@@/guides/how-to-study/">How to Study Effectively</a>. To turn a study plan into a schedule, use the <a href="@@/tools/study-timer/">study timer</a> and <a href="@@/tools/flashcards/">flashcards</a>.</p>
<h2>Study skills videos</h2>{vids(["notes", "memory", "exams", "practice"])}</section></div>''' + lead_band("Stuck on a class?", "Get matched with free resources and vetted tutors for any subject — online or local, for students and adult learners.", "Tutoring")
    page("study/", "Study Hub: Free High School Study Guides", "Free high school study guides for math, biology, chemistry, physics, English, history, government, economics, computer science, psychology and world languages.", body, [("Study Hub", "")], keywords="high school study guides, free study guide, homework help")
